import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C' if history[-1][1] == 'C' else 'D'

    # Last round: exploit aggressively
    if n >= 99:
        opp_c = sum(1 for a, b in history if b == 'C')
        if opp_c * 100 >= n * 50:
            return 'D'
        return 'D' if history[-1][1] == 'C' else 'C'

    # Endgame: gradually shift to exploitation if opponent is cooperative
    if n >= 90:
        opp_c = sum(1 for a, b in history if b == 'C')
        if opp_c * 100 >= n * 70:
            return 'D'
        if opp_c * 100 >= n * 40:
            return 'C' if history[-1][1] == 'C' else 'D'
        return 'D'

    # Count defections
    opp_d = 0
    my_d = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_d += 1
        if history[i][0] == 'D':
            my_d += 1

    last_my, last_opp = history[-1]

    # Detect always-defect: if opponent has defected a lot recently
    recent_n = 6 if n >= 6 else n
    recent_opp_d = 0
    for i in range(n - recent_n, n):
        if history[i][1] == 'D':
            recent_opp_d += 1

    # If opponent heavily defective overall, defect
    if n >= 10 and opp_d * 100 >= n * 80:
        return 'D'

    # Strong retaliation for sustained recent defection
    if recent_opp_d >= 4:
        return 'D'

    # If opponent just defected
    if last_opp == 'D':
        # Count consecutive opponent defections at tail
        streak = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                streak += 1
            else:
                break
        # If long streak, keep defecting
        if streak >= 3:
            return 'D'
        # If opponent was mostly cooperative overall, retaliate once then forgive
        if n >= 8 and opp_d * 100 <= n * 20:
            # Tit-for-tat response: defect once
            if last_my == 'D':
                return 'C'
            return 'D'
        # Mixed: mostly defect but occasionally forgive
        if rng.random() < 0.6:
            return 'D'
        return 'C'

    # Opponent cooperated last round
    # If we defected and opponent still cooperated, punish ourselves slightly by cooperating
    # Preserve mutual cooperation
    # Exploit heavily cooperative opponents occasionally in mid-game
    if n >= 25 and n < 85 and opp_d * 100 <= n * 8:
        if my_d * 100 <= n * 10:
            # We've been very cooperative; probe occasionally
            if rng.random() < 0.12:
                return 'D'
        return 'C'

    # If recent opponent defections were 1-3, resume cooperation if they cooperated last
    if recent_opp_d <= 2:
        return 'C'

    return 'C'
